@DarkLight1337 if fails now to pass response_format='json_object" and guided_json at same time.  It didn't fail before.  

Repro as follows.

Just breaks things if had been setting response_format.  This is only a hassle to rebuild products with old behavior that didn't fail.

Just comment response_format to see it not fail. 

Only fails after this PR.

```
import jsonschema
import json
import openai

TEST_SCHEMA = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },
        "age": {
            "type": "integer"
        },
        "skills": {
            "type": "array",
            "items": {
                "type": "string",
                "maxLength": 10
            },
            "minItems": 3
        },
        "work history": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "company": {
                        "type": "string"
                    },
                    "duration": {
                        "type": "string"
                    },
                    "position": {
                        "type": "string"
                    }
                },
                "required": ["company", "position"]
            }
        }
    },
    "required": ["name", "age", "skills", "work history"]
}

def test_guided_json_chat():
    client = openai.OpenAI(
        base_url="FILL ME",
        api_key="FILL ME",
    )
    MODEL_NAME = 'meta-llama/Meta-Llama-3.1-405B-Instruct-FP8'
    messages = [{
        "role": "system",
        "content": "you are a helpful assistant"
    }, {
        "role":
            "user",
        "content":
            f"Give an example JSON for an employee profile that "
            f"fits this schema: {TEST_SCHEMA}"
    }]
    chat_completion = client.chat.completions.create(
        model=MODEL_NAME,
        messages=messages,
        max_tokens=500,
        response_format=dict(type="json_object"),
        extra_body=dict(guided_json=TEST_SCHEMA))
    message = chat_completion.choices[0].message
    assert message.content is not None
    json1 = json.loads(message.content)
    jsonschema.validate(instance=json1, schema=TEST_SCHEMA)
    print(json1)

if __name__ == "__main__":
    test_guided_json_chat()
```
